/// <summary>
/// MPJ_28155_SalesFinalisation 3.6.3 Sales order shipments and 3.7.2 Periodic task
/// Main SO shipment creation service class
/// </summary>
class METSalesOrderShipmentCreationService extends SysOperationServiceBase
{
    boolean runBatch = false;

}

Method.Source:
    /// <summary>
    /// run method called from workbench controller class
    /// </summary>
    /// <param name = "_contract"><c>METSalesOrderShipmentCreationContract</c> contract class with salesOrderRecordSortedList object initialized</param>
    void run(METSalesOrderShipmentCreationContract _contract)
    { 
        Map shipmentMap;

        // Create the map with the earliest shipdate and variables to use per customer
        shipmentMap = this.createShipmentMap(_contract.parmSalesOrderRecordSortedList());

        // create shipments
        this.createShipments(shipmentMap, _contract.parmSalesOrderRecordSortedList());
    }

    /// <summary>
    /// 3.7.2 Periodic task
    /// runBatch method called from batch controller class
    /// </summary>
    /// <param name = "_contract"><c>METSalesOrderShipmentCreationContract</c> contract class with query object initialized</param>
    void runBatch(METSalesOrderShipmentCreationContract _contract)
    {     
        Query query = _contract.getQuery();

        // set class variable to identify runBatch scenario
        runBatch = true;

        // update query ranges for warehouse and ship date
        query = this.updateQuery(query);

        // create sales order RecordSortedList to process from query
        RecordSortedList salesOrderList = this.createRecordSortedList(query);

        // set the RecordSortedList in the contract so we can use it in the run method
        _contract.parmSalesOrderRecordSortedList(salesOrderList);

        this.run(_contract);
    }

    /// <summary>
    /// Update query at runtime to add filters on requested ship date OR confirmed ship date AND warehouse OR secondary warehouse
    /// Multiple batch tasks with different queries won't work as we need to consolidate multiple SO in a shipment
    /// </summary>
    /// <param name = "_query"><c>Query</c> from the batch controller</param>
    /// <returns>updated <c>Query</c> object</returns>
    Query updateQuery(Query _query)
    {       
        // Update warehouse range
        this.updateQueryRangeWarehouse(_query);

        // Update ship date range
        this.updateQueryRangeShipdate(_query);

        return _query;
    }

    /// <summary>
    /// Update the warehouse query range to manage primary or secondary warehouse
    /// currently only managing single/multiple comma separated warehouse ids
    /// </summary>
    /// <param name = "_query"><c>Query</c> object from the batch</param>
    /// <returns>updated <c>Query</c> object with primary or secondary warehouse filters</returns>
    Query updateQueryRangeWarehouse(Query _query)
    {
        QueryBuildDataSource qbdsSalesTable, qbdsMetSalesTable, qbdsMetInventLocation, qbdsMetSecondaryInventLocation;
        str warehouseFilterValue;
        QueryBuildRange warehouseQbr;
        container conWarehouseFilterValue;
        int i;
        const str space = ' ';
        const str comma = ',';

        qbdsSalesTable = _query.dataSourceTable(tableNum(SalesTable));
        qbdsMetSalesTable = _query.dataSourceTable(tableNum(METSalesTable));
        qbdsMetInventLocation = _query.dataSourceTable(tableNum(METInventLocation), 2);
        qbdsMetSecondaryInventLocation = _query.dataSourceTable(tableNum(METInventLocation), 1);
        
        warehouseQbr = qbdsSalesTable.findRange(fieldNum(SalesTable, InventLocationId));
    
        warehouseFilterValue = warehouseQbr.value();

        // remove space from filter value and convert into a container
        conWarehouseFilterValue = str2con_RU(strRem(warehouseFilterValue, space), comma);

        // if only 1 warehouse, update the current range value else add a new range value
        for (i = 1 ; i <= conLen(conWarehouseFilterValue) ; i++)
        {

            if (i == 1)
            {
                // for RDC filter by warehouse and warehouse auto shipment = yes
                // for NDC filter by secondary warehouse and secondary warehouse auto shipment = yes
                warehouseQbr.value(strFmt('(((%1 == "%2") && (%3.%4 == %5)) || ((%6.%7 == "%2") && (%8.%4 == %5)))',
                                                                                     fieldStr(SalesTable, InventLocationId),
                                                                                     queryValue(conPeek(conWarehouseFilterValue, i)),
                                                                                     qbdsMetInventLocation.name(),
                                                                                     fieldStr(METInventLocation, AutoShipment),
                                                                                     any2Int(NoYes::Yes),
                                                                                     qbdsMetSalesTable.name(),
                                                                                     fieldStr(METSalesTable, SecondaryInventLocationId),
                                                                                     qbdsMetSecondaryInventLocation.name()));
            }
            else
            {
                qbdsSalesTable.addRange(fieldNum(SalesTable, InventLocationId)).value(strFmt('(((%1 == "%2") && (%3.%4 == %5)) || ((%6.%7 == "%2") && (%8.%4 == %5)))',
                                                                                     fieldStr(SalesTable, InventLocationId),
                                                                                     queryValue(conPeek(conWarehouseFilterValue, i)),
                                                                                     qbdsMetInventLocation.name(),
                                                                                     fieldStr(METInventLocation, AutoShipment),
                                                                                     any2Int(NoYes::Yes),
                                                                                     qbdsMetSalesTable.name(),
                                                                                     fieldStr(METSalesTable, SecondaryInventLocationId),
                                                                                     qbdsMetSecondaryInventLocation.name()));
            }
        }

        return _query;
    }

    /// <summary>
    /// Update the shipdate query range to manage requested shipdate and confirmed shipdate
    /// currently only managing DayRange() and single date
    /// </summary>
    /// <param name = "_query"><c>Query</c> object from the batch</param>
    /// <returns>updated <c>Query</c> object with requested and confirmed shipdate filters</returns>
    Query updateQueryRangeShipdate(Query _query)
    {
        const str dayRange = 'DayRange';
        const str parenthesis = '()';
        const str slash = '/';
        const str backslash = '\\';
        const str doubleQuote = '"';
        int posDayRange;
        str shipDateFilterValue, shipDateFilterValueExtract;
        QueryBuildRange shipDateQbr;
        QueryBuildDataSource qbdsSalesTable = _query.dataSourceTable(tableNum(SalesTable));
        shipDateQbr = qbdsSalesTable.findRange(fieldNum(SalesTable, ShippingDateRequested));
        container conDayRange;

        shipDateFilterValue = shipDateQbr.value();

        posDayRange = strScan(shipDateFilterValue, dayRange, 1, strLen(shipDateFilterValue));

        if (posDayRange)
        {
            // get the values from the DayRange methods
            shipDateFilterValueExtract = strDel(shipDateFilterValue, posDayRange, strLen(dayRange));
            shipDateFilterValueExtract = strRem(shipDateFilterValueExtract, parenthesis);
            conDayRange = str2con(shipDateFilterValueExtract);

            // use the logic as in SysQueryRangeUtil::dayRange
            utcdatetime currentDateTime = DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::getSystemDateTime(), DateTimeUtil::getUserPreferredTimeZone());

            shipDateQbr.value(strFmt('(((%1 >= %2) && (%1 <= %3)) || ((%1 == %4) && ((%5 >= %2) && (%5 <= %3))))',
                                                                              fieldStr(SalesTable, ShippingDateConfirmed),
                                                                                Date2StrXpp(DateTimeUtil::date(DateTimeUtil::addDays(currentDateTime,conPeek(conDayRange, 1)))),
                                                                                Date2StrXpp(DateTimeUtil::date(DateTimeUtil::addDays(currentDateTime,conPeek(conDayRange, 2)))),
                                                                                Date2StrXpp(dateNull()),
                                                                              fieldStr(SalesTable, ShippingDateRequested)));
        }
        else
        {
            // convert the single date to the right format
            shipDateFilterValueExtract = strRem(shipDateFilterValue, doubleQuote);
            shipDateFilterValueExtract = strReplace(shipDateFilterValueExtract, slash, backslash);
            
            shipDateQbr.value(strFmt('((%1 == %2) || ((%1 == %3) && (%4 == %2)))',
                                                    fieldStr(SalesTable, ShippingDateConfirmed),
                                                    shipDateFilterValueExtract,
                                                    Date2StrXpp(dateNull()),
                                                    fieldStr(SalesTable, ShippingDateRequested)));
        }

        return _query;
    }

    /// <summary>
    /// Create RecordSortedList from a query for the batch scenario
    /// </summary>
    /// <param name = "_query">updated <c>Query</c> object from the batch job</param>
    /// <returns>list of sales orders to process</returns>
    RecordSortedList createRecordSortedList(Query _query)
    {
        QueryRun queryRun;
        SalesTable salesTable;
        RecordSortedList salesOrderList = new RecordSortedList(tableNum(SalesTable));

        // shipment id needs to be allocated in the ascending order of route stops per route
        salesOrderList.sortOrder(fieldnum(SalesTable, METRoute),
                                 fieldnum(SalesTable, METRouteStopNum),
                                 fieldnum(SalesTable, RecId));

        queryRun = new QueryRun(_query);

        // Execute the query
        while (queryRun.next())
        {
            salesTable = queryRun.get(tableNum(SalesTable));            

            // Check if all SO for a customer/route combination are picked
            if (!SalesTable::METexistSalesOrderNotPicked(salesTable.SalesId, salesTable.CustAccount, salesTable.METRoute))
            {
                salesOrderList.ins(salesTable);
            }
            else
            {
                warning(strFmt("@MET:SONotPicked",salesTable.SalesId));
            }
        }
        return salesOrderList;
    }

    /// <summary>
    /// Method to initialize the map with earliest ship date sales order fields e.g. shipment id, route, route stop, carrier etc...
    /// </summary>
    /// <param name = "_salesOrderList"><c>RecordSortedList</c> of SalesTable sorted by route and route stop</param>
    /// <returns><c>Map</c> object mapping customer id to container of sales order fields for earliest ship date</returns>
    Map createShipmentMap(RecordSortedList _salesOrderList)
    {
        boolean             moreRecords;
        SalesTable          salesTable;
        Map                 shipmentMap = new Map(Types::String, Types::Container);
        container           con;
        SalesShippingDate   salesOrdershipDate;
        METShipmentId       shipmentId;
        NumberSeq           numberSeq;
        TMSCarrierCode      carrierCode;
        METSalesTable       metSalesTable;
                
        moreRecords = _salesOrderList.first(salesTable);
        
        // Loop through the recordSortedList sorted by route and route stop to create shipment ids
        while (moreRecords)
        {
            // get ship date from confirmed ship date if populated else get requested ship date
            salesOrdershipDate = salesTable.ShippingDateConfirmed ? salesTable.ShippingDateConfirmed : salesTable.ShippingDateRequested;
            
            // get shipping carrier
            carrierCode = TMSSalesTable::find(salesTable.SalesId).CarrierCode;
            
            // get custom SalesTable for secondary route and order split group
            metSalesTable = salesTable.metSalesTable();

            // check if a shipment id already allocated to the customer
            if (!shipmentMap.exists(salesTable.CustAccount))
            {
                // Create a new shipment id
                numberSeq = NumberSeq::newGetNum(WHSParameters::numRefMetShippingID());
                shipmentId = numberSeq.num();

                // container to save in the map against the customer                
                con = [shipmentId, salesTable.METRoute, salesTable.METRouteStopNum, salesOrdershipDate, carrierCode, metSalesTable.SecondRoute, metSalesTable.OrderSplitGroup];

                // add it to the map against the customer
                shipmentMap.insert(salesTable.CustAccount, con);
            }
            else
            {
                // check the ship date and update to earliest
                con = shipmentMap.lookup(salesTable.CustAccount);

                // if sales order ship date is earlier than the one in the container
                if (salesOrdershipDate < conPeek(con, 4))
                {
                    // A list of sales orders belonging to one customer with all the orders bearing the same primary route (and blank secondary route),
                    // but different ship dates, if selected in the workbench, will result in one shipment record bearing the earliest shipment date from the current date.
                    con = conPoke(con, 2, salesTable.METRoute);
                    con = conPoke(con, 3, salesTable.METRouteStopNum);
                    con = conPoke(con, 4, salesOrdershipDate);
                    con = conPoke(con, 5, carrierCode);
                    con = conPoke(con, 6, metSalesTable.SecondRoute);
                    con = conPoke(con, 7, metSalesTable.OrderSplitGroup);
                    
                    // update earliest ship date and primary route in the map against the customer
                    shipmentMap.insert(salesTable.CustAccount, con);
                }

            }

            // select the next sales order from the soList
            moreRecords = _salesOrderList.next(salesTable);

        }

        return shipmentMap;
    }

    /// <summary>
    /// Create shipments from map and RecordSortedList
    /// </summary>
    /// <param name = "_shipmentMap">Map containing variable to use to create shipment per customer</param>
    /// <param name = "_salesOrderList">List of sales orders to create shipments from</param>
    void createShipments(Map _shipmentMap, RecordSortedList _salesOrderList)
    {
        METShipmentTable        shipmentTable;
        METShipmentLine         shipmentLine;
        METRoute                primaryRoute;
        METRouteStop            routeStop;
        SalesTable              salesTable;
        container               con;
        SalesShippingDate       salesOrdershipDate;
        METShipmentId           shipmentId;
        METLoadId               loadId;
        NumberSeq               numberSeq;
        TMSCarrierCode          carrierCode;
        METSecondRoute          secondRoute;
        METOrderSplitGroup      orderSplitGroup;
        boolean moreRecords;
        
        moreRecords = _salesOrderList.first(salesTable);

        boolean createLoad = true;

        // insert selected records in a recordSortedList sorted by route and route stops ascending
        while (moreRecords)
        {
            // for batch
            if (runBatch)
            {
                // If there are certain orders belonging to same route were not previously picked when the original load was generated and subsequently picked during the periodic task run 
                // then allocate the original load id to the newly created shipment instead of creating a new load against it
                loadId = METShipmentTable::findRoute(salesTable.METRoute).LoadId;

                if (!loadId)
                {
                    numberSeq = NumberSeq::newGetNum(WHSParameters::numRefMETLoadId());
                    loadId = numberSeq.num();
                }
            }            
            // For workbench, create one load for all selected shipments
            else if (createLoad && !runBatch)
            {
                numberSeq = NumberSeq::newGetNum(WHSParameters::numRefMETLoadId());
                loadId = numberSeq.num();
                createLoad = false;
            }            
            
            // check if a shipment id already allocated to the customer
            if (_shipmentMap.exists(salesTable.CustAccount))
            {
                // Get variables from container
                con = _shipmentMap.lookup(salesTable.CustAccount);
                shipmentId = conPeek(con, 1);
                primaryRoute = conPeek(con, 2);
                routeStop = conPeek(con, 3);
                salesOrdershipDate = conPeek(con, 4);
                carrierCode = conPeek(con, 5);
                secondRoute = conPeek(con, 6);
                orderSplitGroup = conPeek(con, 7);

                // if the shipment header does not exist
                if (!METShipmentTable::exist(conPeek(con, 1)))
                {
                    // create shipment header
                    shipmentTable.clear();
                    shipmentTable.initValue();
                    shipmentTable.ShipmentId = shipmentID;
                    shipmentTable.initFromSalesTable(salesTable);
                    shipmentTable.LoadId    = loadId;
                    shipmentTable.ShipDate  = salesOrdershipDate;
                    shipmentTable.CarrierCode  = carrierCode;
                    shipmentTable.PrimaryRoute = primaryRoute;
                    shipmentTable.RouteStop = routeStop;
                    shipmentTable.SecondRoute = secondRoute;

                    // The shipment status of for batch shipments needs to be in ‘loaded’ status
                    if (runBatch)
                    {
                        shipmentTable.ShipmentStatus = WHSShipmentStatus::Loaded;
                    }

                    if (shipmentTable.validateWrite())
                    {
                        shipmentTable.insert();
                    }
                }

                // Create shipment lines
                shipmentLine.clear();
                shipmentLine.initValue();
                shipmentLine.ShipmentId = shipmentId;
                shipmentLine.SalesId = salesTable.SalesId;
                shipmentLine.LineNum = METShipmentLine::lastLineNum(shipmentId) + 1;
                shipmentLine.OrderSplitGroup = orderSplitGroup;

                // Hazardous material
                shipmentLine.HazardousMaterial = salesTable::METexistHazardousMaterial(salesTable.SalesId);

                if (shipmentLine.validateWrite())
                {
                    shipmentLine.insert();
                }
            }

            // select the next sales order from the soList
            moreRecords = _salesOrderList.next(salesTable);
        }
    }
